import pandas as pd


def top2(sales):
    rev = (sales.assign(revenue=sales["quantity"] * sales["price"])
           .groupby(["store", "product"], as_index=False)["revenue"].sum())
    rev = rev.sort_values(["store", "revenue"], ascending=[True, False])
    return rev.groupby("store").head(2).reset_index(drop=True)

