import pandas as pd


def to_long(readings):
    long = readings.melt(id_vars="day", var_name="room", value_name="temperature").dropna(subset=["temperature"])
    long["room"] = long["room"].str.replace("temp_room_", "", regex=False)
    return long.sort_values(["day", "room"]).reset_index(drop=True)
